<?php

declare(strict_types=1);

namespace MaikSchneider\SolrShield\EventListener;

use MaikSchneider\SolrShield\Service\TokenService;
use TYPO3\CMS\Core\Site\Entity\Site;
use TYPO3\CMS\Frontend\Event\AfterLinkIsGeneratedEvent;

/**
 * Encodes tx_solr parameters in every link generated by typolink() into a
 * signed obfuscation payload, mirroring AfterUriIsProcessedEventListener.
 */
final readonly class AfterLinkIsGeneratedEventListener
{
    public function __construct(
        private TokenService $tokenService,
    ) {
    }

    public function __invoke(AfterLinkIsGeneratedEvent $event): void
    {
        if (!$this->isObfuscationEnabled()) {
            return;
        }

        $url = $event->getLinkResult()->getUrl();
        $queryString = (string)parse_url($url, PHP_URL_QUERY);

        if ($queryString === '') {
            return;
        }

        parse_str($queryString, $allParams);

        $txSolrParams = array_filter(
            $allParams,
            static fn (int|string $key): bool => str_starts_with((string)$key, 'tx_solr'),
            ARRAY_FILTER_USE_KEY
        );

        if ($txSolrParams === []) {
            return;
        }

        // Solr's SearchUriBuilder first builds a cacheable link template that
        // carries ###tx_solr:...### placeholders, then substitutes the real
        // values into the raw URL and finally dispatches AfterUriIsProcessedEvent.
        // Encoding the template here would bury the placeholder inside the _ss
        // payload, breaking both Solr's str_replace() substitution and the
        // later AfterUriIsProcessedEventListener. Skip template links and let
        // that listener encode the resolved URI instead.
        if ($this->containsRoutingPlaceholder($txSolrParams)) {
            return;
        }

        $otherParams = array_filter(
            $allParams,
            static fn (int|string $key): bool => !str_starts_with((string)$key, 'tx_solr'),
            ARRAY_FILTER_USE_KEY
        );

        $payload = base64_encode((string)json_encode([
            'p' => http_build_query($txSolrParams),
            's' => $this->tokenService->generateToken(),
        ]));

        $newQuery = http_build_query(array_merge($otherParams, ['_ss' => $payload]));
        $newUrl = preg_replace('/\?.*$/', '', $url) . ($newQuery !== '' ? '?' . $newQuery : '');

        $event->setLinkResult(
            $event->getLinkResult()->withAttribute('href', $newUrl)
        );
    }

    /**
     * Recursively checks whether any value still contains a Solr routing
     * placeholder (e.g. ###tx_solr:page###), which marks an unresolved link
     * template that must not be obfuscated yet.
     */
    private function containsRoutingPlaceholder(array $params): bool
    {
        foreach ($params as $value) {
            if (is_array($value)) {
                if ($this->containsRoutingPlaceholder($value)) {
                    return true;
                }
                continue;
            }
            if (is_string($value) && str_contains($value, '###')) {
                return true;
            }
        }
        return false;
    }

    private function isObfuscationEnabled(): bool
    {
        return (bool)$this->readSiteSetting('solrShield.uriObfuscation.enabled', true);
    }

    private function readSiteSetting(string $key, mixed $default): mixed
    {
        $request = $GLOBALS['TYPO3_REQUEST'] ?? null;
        if ($request === null) {
            return $default;
        }
        $site = $request->getAttribute('site');
        if (!$site instanceof Site) {
            return $default;
        }
        return $site->getSettings()->get($key, $default);
    }
}
